insert into public.listings (id, provider_id, category_id, title, slug, brand, model, condition, age_years, last_serviced_at, description, specs, included_accessories, day_cents, weekend_cents, week_cents, month_cents, hold_cents, hold_with_waiver_cents, late_fee_cents_per_hour, late_grace_minutes, cleaning_fee_cents, min_days, max_days, prep_hours, same_day_cutoff_minutes, instant_book, pickup_enabled, pickup_address, pickup_lat, pickup_lng, pickup_hours, pickup_hours_label, pickup_instructions, delivery_enabled, delivery_radius_km, delivery_window_hours, delivery_base_cents, delivery_base_km, delivery_per_km_cents, delivery_notes, rules, id_required, min_renter_age, cancellation_policy_id, status, quality_score, rating, rating_count, published_at, created_at, listing_code) values
  ('e86bcc71-d49e-46cc-930b-d5c4e74c1436', 'cc4d9af2-ad86-4ec6-9ef2-736989e02ee7', '9f996e49-3427-464a-9a3b-a5cf45f8731c', 'DeWalt DWE7491 10-in Jobsite Table Saw with Rolling Stand', 'dewalt-dwe7491-10-in-jobsite-table-saw-with-rolling-stand-northlands', 'DeWalt', 'DWE7491RS', 'Excellent', 3, '2026-08-21'::date, 'Contractor-grade 10-inch jobsite saw with the rack-and-pinion fence that keeps rip cuts parallel, mounted on DeWalt''s rolling stand so one person can move and set it up. Comes with a fresh 24T framing blade fitted; a 60T fine-finish blade is available as an extra. Serviced monthly — belts, arbor and fence alignment are checked and logged.', '[{"key":"Blade","value":"10 in · 24T fitted"},{"key":"Rip capacity","value":"32½ in right · 22 in left"},{"key":"Motor","value":"15 A · 4,800 rpm"},{"key":"Max cut depth","value":"3⅛ in at 90° · 2¼ in at 45°"},{"key":"Weight","value":"41 kg with stand"},{"key":"Power","value":"120 V · dedicated 15 A outlet"}]'::jsonb, array['Rolling stand','Rip fence','Mitre gauge','Push stick','Blade wrenches ×2','2½ in dust port adapter']::text[], 5800, 15000, 21000, 64000, 30000, 10000, 1500, 60, 2500, 1, 30, 4, 120, true, true, '42 Foundry Rd, Northlands', 44.638865, -63.57, '{"label":"Mon–Sat 07:00–18:00","days":{"mon":["07:00","18:00"],"tue":["07:00","18:00"],"wed":["07:00","18:00"],"thu":["07:00","18:00"],"fri":["07:00","18:00"],"sat":["07:00","18:00"],"sun":null}}'::jsonb, 'Mon–Sat 07:00–18:00', 'Drive through the gate to bay 2. Bring photo ID. We load the saw and stand into your vehicle — a hatchback or larger is needed.', true, 15, 2, 2500, 5, 150, 'Price shown to renters includes collection. Delivery slots come from Van 1''s calendar; Sunday collections only 16:00–18:00.', array['Renter must be 18+ and show photo ID at handoff','No wet cutting, masonry or metal','Return clean with all accessories — $25 cleaning fee otherwise','Late return $15/hour after a 1-hour grace period']::text[], true, 18, 'flexible', 'published', 96, 4.9, 87, '2024-03-19T04:00:00.000Z'::timestamptz, '2024-03-17T04:00:00.000Z'::timestamptz, default),
  ('79481506-f266-4893-98c9-e36193289bf9', 'cc4d9af2-ad86-4ec6-9ef2-736989e02ee7', '9f996e49-3427-464a-9a3b-a5cf45f8731c', 'SawStop JSS-120A60 Jobsite Saw Pro', 'sawstop-jss-120a60-jobsite-saw-pro-northlands', 'SawStop', 'JSS-120A60', 'Excellent', 1.5, '2026-08-30'::date, 'Jobsite saw with SawStop''s flesh-detecting brake and a 25½ in rip capacity on a fold-and-roll cart. Ideal for site work where a safe saw matters. One spare brake cartridge is included; if it fires, the cartridge is billed at cost.', '[{"key":"Blade","value":"10 in · 40T fitted"},{"key":"Rip capacity","value":"25½ in"},{"key":"Motor","value":"15 A · 4,000 rpm"},{"key":"Max cut depth","value":"3⅛ in"},{"key":"Weight","value":"37 kg"},{"key":"Power","value":"120 V · 15 A"}]'::jsonb, array['Fold-and-roll cart','Rip fence','Mitre gauge','Push stick','Spare brake cartridge','Dust port adapter']::text[], 7900, 20000, 29000, 88000, 40000, 13000, 1500, 60, 2500, 1, 30, 3, 120, true, true, '42 Foundry Rd, Northlands', 44.638865, -63.57, '{"label":"Mon–Sat 07:00–18:00","days":{"mon":["07:00","18:00"],"tue":["07:00","18:00"],"wed":["07:00","18:00"],"thu":["07:00","18:00"],"fri":["07:00","18:00"],"sat":["07:00","18:00"],"sun":null}}'::jsonb, 'Mon–Sat 07:00–18:00', 'Drive through the gate to bay 2. Bring photo ID. We load the saw and stand into your vehicle — a hatchback or larger is needed.', true, 15, 2, 2500, 5, 150, 'Price shown to renters includes collection. Delivery slots come from Van 1''s calendar; Sunday collections only 16:00–18:00.', array['Renter must be 18+ and show photo ID at handoff','No wet cutting, masonry or metal','Return clean with all accessories — $25 cleaning fee otherwise','Late return $15/hour after a 1-hour grace period']::text[], true, 18, 'flexible', 'published', 92, 5, 12, '2025-04-23T04:00:00.000Z'::timestamptz, '2025-04-21T04:00:00.000Z'::timestamptz, default),
  ('99a8d48a-9827-4746-8baa-2d42f1cfec4d', 'cc4d9af2-ad86-4ec6-9ef2-736989e02ee7', '6169fd30-9f3b-4fa9-8160-06c8040770e4', 'Honda EU2200i Inverter Generator', 'honda-eu2200i-inverter-generator-northlands', 'Honda', 'EU2200i', 'Excellent', 2, '2026-08-12'::date, 'Quiet 2,200 W inverter generator — runs a fridge, lights and a sound system for a garden party, or power tools on a site without mains. Oil checked and fuel at ¾ at every handoff. Two units can be paralleled with the included cable for 4,400 W.', '[{"key":"Output","value":"2,200 W peak · 1,800 W rated"},{"key":"Noise","value":"48–57 dBA"},{"key":"Run time","value":"up to 8.1 h at ¼ load"},{"key":"Fuel","value":"0.95 gal tank · unleaded"},{"key":"Weight","value":"21 kg"},{"key":"Outlets","value":"2 × 120 V 20 A · 12 V DC"}]'::jsonb, array['Parallel cable','Fuel cap','Manual','12 V charging leads']::text[], 4500, 12000, 20000, 62000, 25000, 8000, 1200, 60, 2000, 1, 30, 2, 120, true, true, '42 Foundry Rd, Northlands', 44.638865, -63.57, '{"label":"Mon–Sat 07:00–18:00","days":{"mon":["07:00","18:00"],"tue":["07:00","18:00"],"wed":["07:00","18:00"],"thu":["07:00","18:00"],"fri":["07:00","18:00"],"sat":["07:00","18:00"],"sun":null}}'::jsonb, 'Mon–Sat 07:00–18:00', 'Collect from bay 1. We start it with you and show the eco-throttle switch.', true, 15, 2, 2500, 5, 150, 'Price shown to renters includes collection. Delivery slots come from Van 1''s calendar; Sunday collections only 16:00–18:00.', array['Outdoor use only — never inside or near openings','Fuel is billed at cost if returned below ¾','Return with fuel cap and parallel cable','Late return $12/hour after a 1-hour grace period']::text[], true, 18, 'flexible', 'published', 94, 4.9, 64, '2024-06-27T04:00:00.000Z'::timestamptz, '2024-06-25T04:00:00.000Z'::timestamptz, default),
