insert into public.disputes (id, code, claim_id, booking_id, claimant_provider_id, respondent_profile_id, summary, statements, assignee_staff_id, opened_at, decision_due_at, status, internal_notes, evidence_areas, last_event, last_event_at, claimant_profile_id, respondent_provider_id, decision, charged_cents, released_cents, paid_to_provider_cents, reasoning, resolved_at, appeal_by) values
  ('bffd9b54-4d59-4e65-8ae9-42d0ab8fae5e', 'D-0912', '76036606-c114-4985-8c24-ec72d5a56965', '778eacde-47ab-4287-b2e1-26bd9cd0455c', 'cc4d9af2-ad86-4ec6-9ef2-736989e02ee7', 'd43cd6a7-8b92-4c3d-9d8a-de43353f3c85', 'Damage claim · Hilti TE 70 chuck · $180 + $15 late', '[{"side":"provider","author":"Dana O.","at":"2026-09-04T18:18:00.000Z","body":"Chip of ~12 mm out of the TE-Y chuck collar, not present at handoff (photo 2 shows the collar intact). Hilti quote for collar replacement $164 + 1 h labour $16 = $180. Tool is usable but the collar seal is compromised.","attachments":[{"name":"Hilti quote.pdf"},{"name":"Service log"}]},{"side":"renter","author":"Jonas K.","at":"2026-09-04T18:40:00.000Z","body":"I used it for two days of concrete drilling as the listing allows and never dropped it. I noticed the chip when packing up Thursday evening — I think it was already there under grime at handoff; photo 2 is taken from the other side. Happy to pay something toward it but not the whole collar.","attachments":[{"name":"2 photos · Thu 18:22","count":2}]}]'::jsonb, null, '2026-09-04T18:40:00.000Z'::timestamptz, '2026-09-06T18:40:00.000Z'::timestamptz, 'awaiting_decision', '[{"author":"Ola R.","at":"2026-09-04T20:05:00.000Z","body":"Handoff photo 2 shows the collar from the same angle as the return photo — chip is not visible, grime is light. Renter''s Thursday-evening photos predate return and show the chip, consistent with damage during rental. Wear-and-tear allowance for a 3-year-old tool: apply 20%."}]'::jsonb, '[{"area":"Chuck","handoff_index":1,"return_index":1,"matched_angle":true},{"area":"Body","handoff_index":0,"return_index":0,"matched_angle":true},{"area":"Accessories","handoff_index":3,"return_index":3,"matched_angle":false}]'::jsonb, 'Renter disputed', '2026-09-04T18:40:00.000Z'::timestamptz, default, default, default, default, default, default, default, default, default),
  ('a3e0482d-d272-4282-ba22-eebaf93b585e', 'D-0907', 'ca757710-f054-4836-aa19-de793581b0c3', '4c9c929c-1c6a-41ec-b26c-d1e3bedb1e33', default, default, 'Item not as described · Epson projector, dead pixels', '[{"side":"renter","author":"Kestrel Park PTA","at":"2026-08-30T17:00:00.000Z","body":"A cluster of dead pixels in the lower right was visible on every slide at our quiz night. We are asking for $140 back on the $85/day rate.","attachments":[{"name":"3 photos","count":3}]},{"side":"provider","author":"Theo M.","at":"2026-09-02T15:20:00.000Z","body":"The panel was checked before pickup; the marks in the photos look like dust on the lens rather than dead pixels. Happy to offer a $40 goodwill credit.","attachments":[{"name":"Pre-rental test pattern.jpg"}]}]'::jsonb, '0023acfb-b800-40e9-bb05-f114a13ab266', '2026-09-03T08:00:00.000Z'::timestamptz, '2026-09-05T08:00:00.000Z'::timestamptz, 'awaiting_decision', '[]'::jsonb, '[{"area":"Panel","handoff_index":0,"return_index":0,"matched_angle":false}]'::jsonb, 'Provider replied Thu', '2026-09-03T15:20:00.000Z'::timestamptz, 'e6ad6bfc-c625-4edd-8709-06be4d21b256', '8aad541e-de0c-46ab-ac93-4c5ad4d337e1', default, default, default, default, default, default, default),
  ('dab9fb16-75be-44f5-8c86-a015197198cc', 'D-0903', null, '2713b026-ff42-41a0-b29b-9e5b4457092f', default, default, 'No-show at pickup · frame tent · cancellation fee contested', '[{"side":"provider","author":"Millbrook Event Co.","at":"2026-08-29T15:00:00.000Z","body":"Crew arrived at 41 Mill Lane in the 08:00–11:00 window, no answer at the door or phone for 45 minutes. Cancelled as a no-show; 50% of the rental ($170) applies under the Strict policy.","attachments":[{"name":"Crew GPS log"}]},{"side":"renter","author":"Ada B.","at":"2026-08-29T18:30:00.000Z","body":"I messaged on Friday to move the setup to the afternoon and never heard back. I was at work in the morning. I don''t think I should pay the fee.","attachments":[{"name":"Screenshot of message"}]}]'::jsonb, 'e29f57bf-25cb-447e-85f8-89b610fcc5e4', '2026-09-02T19:00:00.000Z'::timestamptz, '2026-09-04T19:00:00.000Z'::timestamptz, 'awaiting_decision', '[{"author":"Ola R.","at":"2026-09-04T13:00:00.000Z","body":"Message thread shows the renter asked to move the window on Fri 17:40; provider read it Sat 07:30 and did not reply before dispatch."}]'::jsonb, '[]'::jsonb, 'Evidence complete', '2026-09-04T13:00:00.000Z'::timestamptz, 'db9d7d36-2070-4fcb-a8f6-ec0071272456', 'e8d29750-1dc0-448b-ba58-17d37b9b357f', default, default, default, default, default, default, default),
  ('37a8c82d-79a5-416f-9818-bc4c4aa28565', 'D-0899', '862b8a61-8e27-4856-828e-146965bcff4e', '57b1879a-90a4-4296-8da7-69385537d885', 'e6a0245f-a84e-4a6d-9ecb-9f83e3d25a15', '0e241419-5043-4b2a-b0ad-2f753c769463', 'Cleaning claim · concrete mixer drum · $120', '[]'::jsonb, 'e29f57bf-25cb-447e-85f8-89b610fcc5e4', '2026-08-24T21:00:00.000Z'::timestamptz, '2026-08-26T21:00:00.000Z'::timestamptz, 'resolved', '[]'::jsonb, '[]'::jsonb, 'Resolved · split 60/40', '2026-09-05T12:50:00.000Z'::timestamptz, default, default, 'uphold_partial', 7200, 12800, 7200, 'Split 60/40 — the drum was returned unwashed but the provider''s cleaning-fee terms were not shown on the listing at the time of booking.', '2026-09-05T12:50:00.000Z'::timestamptz, '2026-09-12T12:50:00.000Z'::timestamptz),
